def feature(texts: tuple) -> float:
    "Difference in punctuation density between text_a and text_b"
    text_a, text_b = texts
    def punctuation_density(text):
        return sum(1 for c in text if not c.isalnum() and not c.isspace()) / len(text) if len(text) > 0 else 0.0

    return abs(punctuation_density(text_a) - punctuation_density(text_b))

def feature(texts: tuple) -> float:
    "Difference in number of unique words between text_a and text_b"
    text_a, text_b = texts
    unique_words_a = len(set(text_a.split()))
    unique_words_b = len(set(text_b.split()))
    return abs(unique_words_a - unique_words_b)

def feature(texts: tuple) -> float:
    "Difference in average word length between text_a and text_b"
    text_a, text_b = texts
    avg_length_a = sum(len(word) for word in text_a.split()) / len(text_a.split()) if text_a.split() else 0
    avg_length_b = sum(len(word) for word in text_b.split()) / len(text_b.split()) if text_b.split() else 0
    return abs(avg_length_a - avg_length_b)

