def feature(texts: tuple) -> float:
    'Difference in the count of stop words between text_a and text_b'
    text_a, text_b = texts
    stop_words = set(['a', 'an', 'the', 'is', 'in', 'on', 'at', 'to', 'and', 'of', 'for', 'with'])
    count_a = sum(1 for word in text_a.split() if word.lower() in stop_words)
    count_b = sum(1 for word in text_b.split() if word.lower() in stop_words)
    return float(count_a - count_b)

