def feature(texts: tuple) -> float:
    "Similarity in sentence structures based on count of clauses"
    text_a, text_b = texts
    def clause_count(text):
        return text.count(',') + text.count('and') + text.count('or')

    return abs(clause_count(text_a) - clause_count(text_b))

def feature(texts: tuple) -> float:
    "Difference in number of sentences between text_a and text_b"
    text_a, text_b = texts
    sentences_a = text_a.count('.') + text_a.count('!') + text_a.count('?')
    sentences_b = text_b.count('.') + text_b.count('!') + text_b.count('?')
    return abs(sentences_a - sentences_b)

def feature(texts: tuple) -> float:
    "Difference in the count of alphanumeric characters between text_a and text_b"
    text_a, text_b = texts
    alnum_a = sum(1 for c in text_a if c.isalnum())
    alnum_b = sum(1 for c in text_b if c.isalnum())
    return abs(alnum_a - alnum_b)
